import heapq

def solution(input_data: str) -> str:
    lines = input_data.strip().split('\n')

    n, m = map(int, lines[0].split())

    # Parse edges and build adjacency list
    edges = []  # (u, v, w, edge_index)
    graph = [[] for _ in range(n + 1)]

    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        edges.append((u, v, w, i + 1))
        graph[u].append((v, w))
        graph[v].append((u, w))

    start_node = int(lines[-1])

    # Dijkstra's algorithm to find shortest distances from start_node
    dist = [float('inf')] * (n + 1)
    dist[start_node] = 0
    pq = [(0, start_node)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                pq.append((dist[v], v))

    # For each vertex (except start_node), select the edge with minimum weight
    # that lies on a shortest path from start_node
    selected_edges = []
    total_weight = 0

    for v in range(1, n + 1):
        if v == start_node:
            continue

        # Find all edges that can be the last edge of a shortest path to v
        candidate_edges = []
        for u, x, w, idx in edges:
            if u == v:
                candidate_edges.append((w, idx, u))
            elif x == v:
                candidate_edges.append((w, idx, u))

        if not candidate_edges:
            continue

        # Select edge with minimum weight
        # Need to satisfy: dist[other] + w == dist[v]
        best_edge = None
        for w, idx, from_node in candidate_edges:
            if from_node == v:
                continue
            if dist[from_node] + w == dist[v]:
                # Only consider edges on shortest path
                if best_edge is None or w < best_edge[0]:
                    best_edge = (w, idx, from_node)

        if best_edge:
            selected_edges.append(best_edge[1])
            total_weight += best_edge[0]

    # Return result
    return f"{total_weight}\n{' '.join(map(str, selected_edges))} "

