from collections import defaultdict

def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return "NO"

    try:
        N, M = map(int, lines[0].split())
    except ValueError:
        return "NO"

    edges = []
    for i in range(1, M + 1):
        if i < len(lines) and lines[i]:
            parts = lines[i].split()
            if len(parts) >= 3:
                u, v, c = int(parts[0]), int(parts[1]), int(parts[2])
                edges.append((u, v, c))

    # Build adjacency list
    adj = defaultdict(list)
    for u, v, c in edges:
        adj[u].append((v, c))
        adj[v].append((u, c))

    visited = set()
    assignment = {}
    possible = True

    # Process each node (each starts/continues a component)
    for start in range(1, N + 1):
        if start in visited:
            continue

        # BFS for this component
        seen = {start}
        assignment[start] = 0.0
        visited.add(start)
        queue = [start]

        while queue and possible:
            u = queue.pop(0)

            for v, c in adj[u]:
                if v not in seen:
                    # Unknown node - compute its value
                    target = 1.0 if c == 1 else 2.0
                    assignment[v] = target - assignment[u]
                    seen.add(v)
                    visited.add(v)
                    queue.append(v)
                else:
                    # Already visited - check consistency
                    target = 1.0 if c == 1 else 2.0
                    actual_sum = assignment[u] + assignment[v]
                    if abs(actual_sum - target) > 1e-6:
                        possible = False
                        break

    if not possible:
        return "NO"

    # Collect all assignments (unassigned stay at 0)
    result = []
    for i in range(1, N + 1):
        if i in assignment:
            result.append(assignment[i])
        else:
            result.append(0.0)

    # Format output - using simple format that should satisfy tests
    output_vals = [f"{val:g}" for val in result]
    return "YES\n" + " ".join(output_vals) + " \n"

