def solution(input_str):
    """
    Solve the Pieguy and Piegirl game problem on a binary tree.

    Uses dynamic programming with post-order traversal to compute
    the optimal value at each node based on whose turn controls the
    final merge operation.
    """
    lines = input_str.strip().split('\n')
    idx = 0

    if len(lines) == 0:
        return ''

    try:
        t_line = lines[idx].strip()
        if t_line == '':
            return ''
        t = int(t_line)
        idx += 1
    except (ValueError, IndexError):
        return ''

    results = []

    for _ in range(t):
        # Skip empty lines between test cases
        while idx < len(lines) and lines[idx].strip() == '':
            idx += 1

        if idx >= len(lines):
            results.append('0')
            continue

        try:
            n = int(lines[idx].strip())
            idx += 1
        except (ValueError, IndexError):
            results.append('0')
            continue

        # Build tree structure
        # nodes[i] = {'left': l, 'right': r, 'type': 'parent'} or 
        #            {'value': v, 'type': 'leaf'}
        nodes = {}

        for i in range(n):
            while idx < len(lines) and lines[idx].strip() == '':
                idx += 1

            if idx >= len(lines):
                break

            node_line = lines[idx].strip()
            idx += 1

            parts = node_line.split()
            if parts[0] == '-1':
                # Internal/parent node
                left = int(parts[1])
                right = int(parts[2])
                nodes[i] = {'left': left, 'right': right, 'type': 'parent'}
            else:
                # Leaf node
                val = int(parts[0])
                nodes[i] = {'value': val, 'type': 'leaf'}

        # Compute recursively using post-order traversal
        def solve(u):
            """
            Returns (result_value, depth) for subtree rooted at u
            - result_value: optimal value from optimal play in subtree
            - depth: number of operations needed to reduce subtree to single leaf
            """
            if u not in nodes:
                return 0, 0

            if nodes[u]['type'] == 'leaf':
                return nodes[u]['value'], 0

            # Process children first (post-order)
            left_val, left_depth = solve(nodes[u]['left'])
            right_val, right_depth = solve(nodes[u]['right'])

            # Total depth includes merges from both children plus the merge at this node
            depth = 1 + left_depth + right_depth

            # Determine whose turn it is based on parity of total moves
            # Odd depth: Pieguy (maximizer) makes final choice
            # Even depth: Piegirl (minimizer) makes final choice
            if depth % 2 == 1:
                return max(left_val, right_val), depth
            else:
                return min(left_val, right_val), depth

        # The game starts with all nodes present. Node 0 is the root.
        # The root's depth represents total moves, but we just need its result value
        if 0 in nodes:
            result, _ = solve(0)
            results.append(str(result))
        else:
            results.append('0')

    return '\n'.join(results)


