        dp[i][j] = 1

    # Fill for increasing lengths
    for length in range(3, n):  # 3 edges means 4 vertices
        for i in range(n):
            j = (i + length - 1) % n
            count = 0
            for k in range(1, length - 1):  # k is the split vertex
                k_actual = (i + k) % n
