    n = int(lines[0])
    t = lines[1]

    m = len(t)

    if m == 0:
        return str(0)

    # Count consecutive double characters in t
    double_count = 0
    for i in range(m - 1):
        if t[i] == t[i+1]:
            double_count += 1

    # The maximum time Appleman needs is n minus the number of doubles in t
    # This is because each double gives Appleman an opportunity to use
    # multi-character substrings to reduce the number of pieces needed
    result = n - double_count

    return str(result)

