def solve(a, b, k, t):
    from collections import defaultdict

    offset = 2 * k * t
    max_diff = 2 * k * t
    size = 2 * max_diff + 1

    dp = [0] * size
    dp[offset] = 1  # Initial difference is 0

    freq_max = 2 * k
    for turn in range(t):
        new_dp = [0] * size
        for diff in range(-offset, offset + 1):
            count = dp[diff]
            if count == 0:
                continue

            # Frequency of difference m - l where m, l ∈ [-k, k]
            # For v = m - l, frequency is 2k + 1 - |v| for |v| ≤ 2k
            for v in range(-freq_max, freq_max + 1):
                freq = 2 * k + 1 - abs(v)
                if freq <= 0:
                    continue
                new_diff = diff + v
                if 0 <= new_diff <= max_diff:
                    new_dp[new_diff] = (new_dp[new_diff] + count * freq) % MOD

        dp = new_dp

    # Find number of games where Memory wins
    # Memory wins if: a + M > b + L where M, L are total increments
    # => M - L > b - a
    # => diff > b - a

    threshold = (b - a) + 1
    winning_games = 0
    for diff in range(threshold, size):
        winning_games = (winning_games + dp[diff]) % MOD

    return winning_games

