    min_prime = list(range(MAX_N + 1))
    primes = []
    for i in range(2, MAX_N + 1):
        if min_prime[i] == i:
            primes.append(i)
            for j in range(i * i, MAX_N + 1, i):
                if min_prime[j] == j:
                    min_prime[j] = i

    # Count distinct prime factors for each n
    distinct_prime_count = [0] * (MAX_N + 1)
    for n in range(1, MAX_N + 1):
        temp = n
        cnt = 0
        while temp > 1:
            p = min_prime[temp]
            cnt += 1
            while temp % p == 0:
                temp //= p
        distinct_prime_count[n] = cnt

    # f0[n] = 2^(distinct prime count of n)
    def get_f0(n):
        if n == 1:
            return 1
        return pow(2, distinct_prime_count[n], MOD)

    # Precompute all divisors for each n
    divisors = [[] for _ in range(MAX_N + 1)]
    for i in range(1, MAX_N + 1):
        for j in range(i, MAX_N + 1, i):
            divisors[j].append(i)

    # Precompute fr values for r from 0 to 1000000
    # fr[n][r] = f_r(n)
    # Space optimization: we can compute iteratively

    # Create tables for fr values
    fr_table = [[0] * (MAX_N + 1) for _ in range(MAX_N + 1)]

    # Base case: f0
    for n in range(1, MAX_N + 1):
        fr_table[0][n] = get_f0(n)

    # Compute fr iteratively
    for r in range(1, MAX_N + 1):
        for n in range(1, MAX_N + 1):
            total = 0
            for d in divisors[n]:
                # f_r(n) = sum of f_{r-1}(d) for all divisors d of n
                total = (total + fr_table[r-1][d]) % MOD
            fr_table[r][n] = total

    # Answer queries
    results = []
    for r, n in queries:
        if r <= MAX_N and n <= MAX_N:
            results.append(str(fr_table[r][n]))
